    storyCore: 'تولى العز بن عبد السلام القضاء والتدريس في مصر، فأبطل المكوس والضرائب الجائرة، ولما رأى الأمراء المماليك يتصرفون كالأحرار قبل أن يثبت عتقهم الشرعي، وقف بصلابة وقال: «نبيعهم لصالح بيت مال المسلمين فيُعتقون بطريق شرعي ويُصرف ثمنهم في مصالح الأمة وجيشها!»، ونادى عليهم في المزاد العلني فرفع ثمنهم حتى دفع السلطان الصالح أيوب الفدية لبيت المال، فلما رجع العز إلى بيته سألته زوجته: ماذا صنعت؟ قال: «يا هذه، رأيتُ السلطان في أبهته فاستصغرته أمام عظمة الله فبعتُ أمراءه!». وفي معركة عين جالوت اشترط على السلطان قطز ألا تُفرض ضريبة على الشعب حتى يخرج السلطان والأمراء كل ما عندهم من الذهب والجواهر أولاً.',
    lesson1: 'استشعار عظمة الله يملأ قلب العالم هيبةً وشجاعةً في إحقاق الحق.',
    lesson2: 'القدوة العملية من القادة قبل مطالبة الشعب بالتضحية.',
    quote: '«استحضرتُ عظمة الله تعالى فصار السلطان بين يديّ كالقط!».',
    source: 'طبقات الشافعية الكبرى للسبكي • البداية والنهاية لابن كثير',
