    storyCore: 'كان الإمام الموفق ابن قدامة المقدسي آية في حسن الخلق، وسماحة الوجه، وعمق الفقه، وشجاعة الجهاد. قال سبط ابن الجوزي: «ما رأى الموفق أحداً إلا تبسم في وجهه حتى قيل: هذا يقتل خصمه بالتبسم!». وكان في المسجد الأموي يعلم الفقراء والعلماء، وفي ساحات الجهاد يتقدم الصفوف مع صلاح الدين الأيوبي في فتح القدس وحطين وهو شيخ كبير حتى جُرحت يده في سبيل الله، وقال العز بن عبد السلام: «ما طابت نفسي بالإفتاء حتى صارت عندي نسخة من المغني للموفق ابن قدامة».',
